"""Grade-independent additional skill tests. Each attempt uses the same standard."""

from typing import Any


def choice(code: str, topic: str, prompt: str, options: tuple[str, str, str, str], answer: int, explanation: str) -> dict[str, Any]:
    return {
        "code": code, "topic": topic, "question_type": "single_choice",
        "question_text": prompt,
        "options": [{"id": str(index), "text": text} for index, text in enumerate(options)],
        "correct_answers": [str(answer)], "explanation": explanation, "weight": 1.0,
    }


def open_task(code: str, topic: str, prompt: str, reference: str, criteria: list[str]) -> dict[str, Any]:
    return {
        "code": code, "topic": topic, "question_type": "open_answer",
        "question_text": prompt, "options": [], "correct_answers": [],
        "explanation": "Оценивается смысл решения по критериям, а не совпадение формулировок.",
        "weight": 2.0, "reference_solution": reference,
        "rubric_criteria": criteria, "critical_criteria": [],
    }


