def available_additional_skills(specialization: str) -> list[tuple[str, str]]:
    return [(code, data["label"]) for code, data in ADDITIONAL_SKILLS.items()
            if specialization in data["specializations"]]


def validate_additional_bank() -> None:
    codes: set[str] = set()
    for skill, data in ADDITIONAL_SKILLS.items():
        if skill not in ADDITIONAL_ALTERNATES:
            raise ValueError(f"Нет второй формы: {skill}")
        for questions in (data["questions"], ADDITIONAL_ALTERNATES[skill]):
            if len(questions) < 5 or sum(q["question_type"] == "open_answer" for q in questions) > 1:
                raise ValueError(f"Некорректное число заданий: {skill}")
            for question in questions:
                if question["code"] in codes:
                    raise ValueError(f"Повтор кода: {question['code']}")
                codes.add(question["code"])
                options = question["options"]
                if question["question_type"] != "open_answer" and (
                    len(options) != 4 or len({option["text"] for option in options}) != len(options)
                    or len(question["correct_answers"]) != 1
                ):
                    raise ValueError(f"Некорректные варианты: {question['code']}")
                if question["question_type"] == "open_answer" and (not question["rubric_criteria"] or question["weight"] <= 1):
                    raise ValueError(f"Некорректная рубрика: {question['code']}")


validate_additional_bank()
